<script setup lang="ts">
import {useEditorDraft,useEditorBoundary,useFormFeedback} from './editorGuard';
import {computed,ref} from 'vue';import {layersOf,layerOf,networkLayersVisible} from './networkLayers';import {roleNames,request} from './model';import type {State,NetworkSegment,NetworkLayer} from './model';
const props=defineProps<{state:State;network:NetworkSegment}>();const emit=defineEmits<{saved:[state:State];busy:[value:boolean]}>();
const savedVisible=networkLayersVisible(props.network);
const draftRevision=ref(props.state.revision);
const layers=ref<NetworkLayer[]>(layersOf(props.network).map(l=>({...l}))),assignments=ref({...props.network.deviceLayers}),busy=ref(false),error=ref(''),message=ref(''),dragged=ref(''),query=ref(''),selection=ref<string[]>([]),target=ref('');
const root=ref<HTMLElement>();useEditorBoundary(root,()=>busy.value);useFormFeedback(root,()=>error.value);
const draft=useEditorDraft(()=>({layers:layers.value,assignments:assignments.value}),()=>busy.value);
function countLayer(id:string){return devices.value.filter(d=>(assignments.value[d.id]||layerOf({...props.network,layers:layers.value,deviceLayers:{}},d.id,role(d.modelId)))===id).length}
function down(id:string){const i=layers.value.findIndex(l=>l.id===id);if(i<0||i>=layers.value.length-1)return;const item=layers.value.splice(i,1)[0];layers.value.splice(i+1,0,item)}
function addLayer(){layers.value.push({id:'layer-'+crypto.randomUUID(),name:'新层 '+(layers.value.length+1)})}
const devices=computed(()=>props.state.devices.filter(d=>props.network.deviceIds.includes(d.id)));
const filtered=computed(()=>devices.value.filter(d=>[d.name,d.assetTag,props.state.models.find(m=>m.id===d.modelId)?.name].join(' ').toLowerCase().includes(query.value.toLowerCase())));
const role=(id:string)=>props.state.models.find(m=>m.id===id)?.role||'server';
function automaticName(id:string,modelId:string){return layers.value.find(l=>l.id===layerOf({...props.network,layers:layers.value,deviceLayers:{}},id,role(modelId)))?.name}
function remove(id:string){if(layers.value.length===1)return;layers.value=layers.value.filter(l=>l.id!==id);for(const device of Object.keys(assignments.value))if(assignments.value[device]===id)delete assignments.value[device];if(target.value===id)target.value=''}
function move(id:string,before:string){const index=layers.value.findIndex(l=>l.id===id),to=layers.value.findIndex(l=>l.id===before);if(index<0||to<0||index===to)return;const item=layers.value.splice(index,1)[0];layers.value.splice(layers.value.findIndex(l=>l.id===before),0,item)}
function assign(){for(const id of selection.value){if(target.value)assignments.value[id]=target.value;else delete assignments.value[id]}}
async function save(){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';try{const next=await request<State>('/networks/'+props.network.id+'/layers','PUT',{revision:draftRevision.value,layersVisible:savedVisible,layers:layers.value.map(l=>({...l,name:l.name.trim()})),deviceLayers:assignments.value});draftRevision.value=next.revision;draft.accept();emit('saved',next);message.value='分层已保存，未受影响的手动位置已保留'}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false)}}
</script>
<template><form ref="root" class="network-layer-editor" @keydown="($event.ctrlKey||$event.metaKey)&&$event.key.toLowerCase()==='s'&&($event.preventDefault(),!busy&&($event.currentTarget as HTMLFormElement).requestSubmit())" @submit.prevent="save"><fieldset class="editor-fieldset" :disabled="busy"><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="message" class="info-banner" role="status">{{message}}</p><section class="layer-configuration" aria-label="排列层设置"><div class="layer-workflow-note"><div><strong>网络包含：组织关系</strong><span>例如管理网络、存储网络，选择网络后在“添加设备”中维护。</span></div><div><strong>排列层：设备排列规则</strong><span>例如核心、接入、计算层。设置层名、顺序与设备分配；显示开关在网络详情中单独操作。</span></div></div><p class="panel-note">先调整层名与顺序，再为设备选择排列层；保存后更新画布。</p><div class="form-section-heading"><h3>{{network.name}} · {{layers.length}} 层</h3><button type="button" class="secondary" :disabled="busy||layers.length>=16" @click="addLayer">新增排列层</button></div>
<div v-for="(layer,index) in layers" :key="layer.id" class="layer-edit-row" :data-layer-editor="layer.id" draggable="true" @dragstart="dragged=layer.id" @dragover.prevent @drop.prevent="move(dragged,layer.id)"><span>⠿ {{index+1}}</span><span class="layer-device-count">{{countLayer(layer.id)}} 台</span><input v-model="layer.name" :aria-label="`第${index+1}层名称`" required maxlength="40"/><button type="button" class="text-button" :disabled="index===0||busy" @click="move(layer.id,layers[index-1].id)">上移</button><button type="button" class="text-button" :disabled="index===layers.length-1||busy" @click="down(layer.id)">下移</button><button type="button" class="text-button danger-text" :disabled="layers.length===1||busy" @click="remove(layer.id)">删除层</button></div>
<div class="form-section-heading"><h3>设备分层</h3><input v-model="query" placeholder="搜索名称、编号或型号" aria-label="筛选分层设备"/></div><div class="quick-selection"><button type="button" class="text-button" @click="selection=[...new Set([...selection,...filtered.map(d=>d.id)])]">全选筛选结果</button><button type="button" class="text-button" @click="selection=[]">清空选择</button><select v-model="target" aria-label="批量目标层"><option value="">按角色自动</option><option v-for="l in layers" :key="l.id" :value="l.id">{{l.name}}</option></select><button type="button" class="secondary" :disabled="!selection.length" @click="assign">分配选中 {{selection.length}} 台</button></div>
<div class="table-scroll"><table><thead><tr><th>选择</th><th>设备</th><th>型号角色</th><th>排列层</th></tr></thead><tbody><tr v-for="d in filtered" :key="d.id"><td><input v-model="selection" type="checkbox" :value="d.id" :aria-label="'选择分层设备 '+d.name"/></td><td>{{d.name}}<small>{{d.assetTag}}</small></td><td>{{roleNames[role(d.modelId)]}}</td><td><select :value="assignments[d.id]||''" :aria-label="'设备排列层 '+d.name" @change="assignments[d.id]=($event.target as HTMLSelectElement).value;!assignments[d.id]&&delete assignments[d.id]"><option value="">自动（{{automaticName(d.id,d.modelId)}}）</option><option v-for="l in layers" :key="l.id" :value="l.id">{{l.name}}</option></select></td></tr></tbody></table></div></section><div class="modal-actions"><span class="muted small">删除层后，其设备恢复自动分层；仅层次或归属变化的设备恢复自动位置，改层名保留手动布局。</span><button class="primary" :disabled="busy">保存分层设置</button></div></fieldset></form></template>
